# ---- verify: old text occurs exactly once in the v2-patched tree ----
bad = 0
for x in M:
    t = (TREE / x["file"]).read_text()
    n = t.count(x["old"])
    if n != 1:
        bad += 1
        print("COUNT", n, x["id"], x["file"], repr(x["old"][:70]))
    if x["old"] == x["new"]:
        print("NOOP", x["id"]); bad += 1
ids = [x["id"] for x in M]
assert len(ids) == len(set(ids)), "duplicate ids"
print(len(M), "mutants;", bad, "problems")
if len(sys.argv) > 2:
    json.dump([{k: x[k] for k in ("id", "file", "old", "new", "desc", "expect", "killer")} for x in M], open(sys.argv[2], "w"), indent=1)
